SELECT 'episode video master' AS k, count(*) AS v, 'Majarra episodes with no stream asset' AS note FROM episodes e JOIN series s ON s.id=e.series_id WHERE s.content_class='production' AND s.status<>'archived' AND e.status<>'archived' AND NOT EXISTS(SELECT 1 FROM asset_links al WHERE al.entity_type='episode' AND al.entity_id=e.id AND al.role IN ('stream','video'));
SELECT 'episode thumbnail 16:9' AS k, count(*) AS v, 'Majarra episodes with no thumbnail' AS note FROM episodes e JOIN series s ON s.id=e.series_id WHERE s.content_class='production' AND s.status<>'archived' AND e.status<>'archived' AND NOT EXISTS(SELECT 1 FROM asset_links al WHERE al.entity_type='episode' AND al.entity_id=e.id AND al.role IN ('thumbnail','still'));
SELECT 'episode voiceover' AS k, count(*) AS v, 'no audio asset of any kind exists in content_assets' AS note FROM episodes e JOIN series s ON s.id=e.series_id WHERE s.content_class='production' AND s.status<>'archived' AND e.status<>'archived';
SELECT 'episode captions' AS k, count(*) AS v, 'no subtitle asset of any kind exists' AS note FROM episodes e JOIN series s ON s.id=e.series_id WHERE s.content_class='production' AND s.status<>'archived' AND e.status<>'archived';
SELECT 'series poster' AS k, count(*) AS v, 'Majarra series with no poster' AS note FROM series s WHERE s.content_class='production' AND s.status<>'archived' AND NOT EXISTS(SELECT 1 FROM asset_links al WHERE al.entity_type='series' AND al.entity_id=s.id AND al.role='poster');
SELECT 'series banner' AS k, count(*) AS v, 'Majarra series with no banner' AS note FROM series s WHERE s.content_class='production' AND s.status<>'archived' AND NOT EXISTS(SELECT 1 FROM asset_links al WHERE al.entity_type='series' AND al.entity_id=s.id AND al.role='banner');
SELECT 'planet cover' AS k, count(*) AS v, 'planets with an icon but no cover' AS note FROM planets p WHERE NOT EXISTS(SELECT 1 FROM asset_links al WHERE al.entity_type='planet' AND al.entity_id=p.id AND al.role='cover');
SELECT 'story page illustration' AS k, count(*) AS v, 'story pages with no image asset' AS note FROM story_pages sp JOIN stories st ON st.id=sp.story_id WHERE st.status<>'archived' AND sp.image_asset_id IS NULL;
SELECT 'story narration audio' AS k, count(*) AS v, 'page localisations with no narration asset' AS note FROM story_page_localizations l JOIN story_pages sp ON sp.id=l.page_id JOIN stories st ON st.id=sp.story_id WHERE st.status<>'archived' AND l.narration_asset_id IS NULL;
SELECT 'story cover' AS k, count(*) AS v, 'active stories with no cover link' AS note FROM stories st WHERE st.status<>'archived' AND NOT EXISTS(SELECT 1 FROM asset_links al WHERE al.entity_type='story' AND al.entity_id=st.id AND al.role='cover');
SELECT 'book illustration and layout' AS k, count(*) AS v, 'books with a manuscript awaiting art and layout' AS note FROM books WHERE pages<>'[]';
SELECT 'game engine implementation' AS k, count(*) AS v, 'game packs specified, none programmed' AS note FROM games WHERE content_pack<>'{}';
SELECT 'character reference art' AS k, count(*) AS v, 'characters with no reference sheet' AS note FROM characters c WHERE NOT EXISTS(SELECT 1 FROM asset_links al WHERE al.entity_type='character' AND al.entity_id=c.id);
SELECT 'character voice casting' AS k, count(*) AS v, 'no voice casting recorded for any character' AS note FROM characters;
SELECT 'activity cover and step photos' AS k, count(*) AS v, 'activities with no cover link' AS note FROM projects p WHERE NOT EXISTS(SELECT 1 FROM asset_links al WHERE al.entity_type='project' AND al.entity_id=p.id);
